import * as THREE from 'three';
import { mulberry32 } from './rng.js';

const HEIGHT_MIN = 8;
const HEIGHT_MAX = 40;

/**
 * Generate a procedural city block: a gridSize x gridSize grid of lots,
 * each containing one box building with a seeded random height.
 *
 * @param {number} seed Seed for the deterministic PRNG.
 * @param {object} [options]
 * @param {number} [options.gridSize=4] Lots per side of the block.
 * @param {number} [options.lot=10] Lot size (world units) per side.
 * @param {number} [options.gapMin=1] Minimum clearance between a building
 *   footprint and its lot borders.
 * @returns {THREE.Group} Group whose children are building meshes, each with
 *   userData { row, col, height }.
 */
export function generateBlock(seed, { gridSize = 4, lot = 10, gapMin = 1 } = {}) {
  if (!Number.isInteger(gridSize) || gridSize < 1) {
    throw new RangeError('gridSize must be a positive integer');
  }
  const maxFootprint = lot - 2 * gapMin;
  if (maxFootprint <= 0) {
    throw new RangeError('gapMin is too large for the given lot size');
  }

  const rand = mulberry32(seed);
  const group = new THREE.Group();
  group.name = `city-block-${seed}`;

  for (let row = 0; row < gridSize; row++) {
    for (let col = 0; col < gridSize; col++) {
      const height = HEIGHT_MIN + rand() * (HEIGHT_MAX - HEIGHT_MAX === 0 ? 0 : HEIGHT_MAX - HEIGHT_MIN);

      // Footprint: seeded random size, always leaving >= gapMin clearance
      // to every lot border.
      const w = gapMin + rand() * (maxFootprint - gapMin);
      const d = gapMin + rand() * (maxFootprint - gapMin);
      // Center offset within the free interior so clearance holds on both sides.
      const freeW = maxFootprint - w;
      const freeD = maxFootprint - d;
      const offX = (rand() - 0.5) * freeW;
      const offZ = (rand() - 0.5) * freeD;

      const centerX = col * lot + lot / 2 + offX;
      const centerZ = row * lot + lot / 2 + offZ;

      const geometry = new THREE.BoxGeometry(w, height, d);
      geometry.translate(0, height / 2, 0); // sit on the ground plane
      const material = new THREE.MeshLambertMaterial({ color: 0x9aa3ad });
      const mesh = new THREE.Mesh(geometry, material);
      mesh.position.set(centerX, 0, centerZ);
      mesh.userData = { row, col, height };
      mesh.name = `building-${row}-${col}`;
      group.add(mesh);
    }
  }

  return group;
}

