import { describe, it, expect } from 'vitest';
import * as THREE from 'three';
import { generateBlock } from '../src/cityBlock.js';
import { mulberry32 } from '../src/rng.js';

/** Snapshot of a generated block: heights and world positions per child. */
function snapshot(group) {
  return group.children.map((m) => ({
    height: m.userData.height,
    position: m.position.toArray(),
  }));
}

describe('generateBlock', () => {
  it('is deterministic: same seed gives identical heights and positions', () => {
    const a = snapshot(generateBlock(1234));
    const b = snapshot(generateBlock(1234));
    expect(b).toStrictEqual(a);
  });

  it('different seeds produce different blocks', () => {
    const a = snapshot(generateBlock(1));
    const b = snapshot(generateBlock(2));
    expect(a).not.toStrictEqual(b);
  });

  it('no two buildings intersect', () => {
    for (const seed of [7, 42, 9999]) {
      const group = generateBlock(seed);
      const boxes = group.children.map((mesh) =>
        new THREE.Box3().setFromObject(mesh)
      );
      for (let i = 0; i < boxes.length; i++) {
        for (let j = i + 1; j < boxes.length; j++) {
          expect(
            boxes[i].intersectsBox(boxes[j]),
            `buildings ${i} and ${j} intersect (seed ${seed})`
          ).toBe(false);
        }
      }
    }
  });

  it('all heights are within [8, 40]', () => {
    for (const seed of [0, 5, 12345]) {
      const group = generateBlock(seed);
      for (const mesh of group.children) {
        expect(mesh.userData.height).toBeGreaterThanOrEqual(8);
        expect(mesh.userData.height).toBeLessThanOrEqual(40);
      }
    }
  });

  it('child count is gridSize squared', () => {
    expect(generateBlock(11).children.length).toBe(16);
    const g = generateBlock(12, { gridSize: 6 });
    expect(g.children.length).toBe(36);
    expect(g).toBeInstanceOf(THREE.Group);
  });
});

describe('mulberry32', () => {
  it('produces deterministic floats in [0, 1)', () => {
    const r1 = mulberry32(99);
    const seq1 = Array.from({ length: 5 }, r1);
    const seq2 = Array.from({ length: 5 }, mulberry32(99));
    expect(seq1).toStrictEqual(seq2);
    for (const v of seq1) {
      expect(v).toBeGreaterThanOrEqual(0);
      expect(v).toBeLessThan(1);
    }
  });
});

